void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // slightly more aggressive reduction to trigger rephasing sooner
    rephase_limit += 1024;  // smaller increment to rephase more frequently

    // Use a combination of local best and random flips based on activity
    for (int i = 1; i <= vars; i++) {
        if (activity[i] > 1e-50) {  // active variables
            // 80% chance to use local best, 20% chance to flip
            if (rand() % 100 < 80) {
                saved[i] = local_best[i];
            } else {
                saved[i] = -local_best[i];
            }
        } else {  // inactive variables get random phase
            saved[i] = (rand() % 2) ? 1 : -1;
        }
    }
}
